pub fn close(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), U::Error>>
where
    T: AsyncWrite,
    U: Encoder,
{
    unsafe {
        ready!(Pin::new_unchecked(&mut self.io).poll_flush(cx))?;
        ready!(Pin::new_unchecked(&mut self.io).poll_shutdown(cx))?;
    }
    Poll::Ready(Ok(()))
}

