        {
            let mut iter = self.ids.intersection(set).into_iter();

            if let Some(first) = iter.next() {
                // Set iterators are increasing so we only need to change start once.
                self.space = cmp::min(self.space, first);
                self.values[first] = None;
                for id in iter {
                    self.values[id] = None;
                }
            }
