        // space should be the minimal empty space.
        for id in 0..self.space {
            assert!(self.ids.contains(id));
        }
        assert!(!self.ids.contains(self.space));
        // values.len() should be an upper bound on ids.
        for id in &self.ids {
            assert!(id < self.values.len())
