impl<T> Iterator for IntoIter<T> {
    type Item = (Id, T);

    #[inline]
    fn next(&mut self) -> Option<Self::Item> {
        let id = self.ids.next()?;
        let n = match self.prev {
            Some(prev) => id - prev - 1,
            None => 0,
        };
        self.prev = Some(id);

        Some((id, self.values.nth(n).unwrap().expect("id not in map")))
    }

    #[inline]
    fn size_hint(&self) -> (usize, Option<usize>) {
        self.ids.size_hint()
    }
}

