        ecall_3(
            ecall::POSEIDON2,
            state_addr as u32 / WORD_SIZE as u32,
            in_buf_addr as u32 / WORD_SIZE as u32,
            out_buf_addr as u32 / WORD_SIZE as u32,
            bits_count,
