    if cfg!(not(feature = "sys-args")) {
        const MSG: &[u8] = "sys_argv is disabled; can be enabled with the sys-args feature flag on risc0-zkvm-platform".as_bytes();
        unsafe { sys_panic(MSG.as_ptr(), MSG.len()) };
    }
    let Return(a0, _) = unsafe {
        syscall_1_nr(
            Syscall::Argv.into(),
            nr::SYS_ARGV,
            out_words,
            out_nwords,
            arg_index as u32,
        )
    };
    a0 as usize
}

