fn drop(&mut self) {
    if self.capacity > 0 {
        unsafe {
            for i in 0..self.size {
                std::ptr::write_volatile(self.p.add(i), 0)
            }
            munlock(self.p, self.capacity);
            let layout = std::alloc::Layout::from_size_align_unchecked(self.capacity, 1);
            std::alloc::dealloc(self.p, layout);
        }
    }
}

