    T: zerocopy::AsBytes + zerocopy::FromBytes + zerocopy::Unaligned,
    F: FnOnce(&mut T),
>(
    &mut self,
    write: F,
) {
    let len = core::mem::size_of::<T>();
    self.write_sized(len, |bytes| {
        let value = unsafe {
            // The `zerocopy` markers ensure this is a safe operation
            &mut *(bytes as *mut _ as *mut T)
        };
        write(value)
    })
}

