fn release_message(&mut self) {
    self.capacity -= 1;
    *self.is_full = self.capacity == 0;

    let channel = unsafe {
        // Safety: the channel_index should always be in-bound if gso_segment is set
        s2n_quic_core::assume!(self.channels.len() > self.channel_index);
